  check('phone frame 390 wide, centred with a vignette; the lab opens as a 420 px side panel; no horizontal scroll', d.w === 390 && d.h <= 800 && d.centred && d.vignette && d.labW === 420 && d.labRight && !d.hscroll, d);
  await shot(page, 'desktop-lab');
