function sourceChecks() {
  section = 'source: ';
  const files = ['index.html', 'style.css', 'cards.js', 'game.js'].map((f) => [f, fs.readFileSync(path.join(GAME_DIR, f), 'utf8')]);
  const lines = files.reduce((a, [, s]) => a + s.split('\n').length, 0);
  check('four plain files total ≤ 6,500 lines (' + lines + ')', lines <= 6500); // Addendum 3 §6 item 37 (cards.js may be ~1,800 of them)
  check('no fetch/XMLHttpRequest/WebSocket/import/module, no remote URLs, no images', files.every(([f, s]) => !/\bfetch\s*\(|XMLHttpRequest|WebSocket|type="module"|^\s*import\s|@import|<img\b|https?:\/\//m.test(s.replace(/data:image\/svg\+xml[^"]*/g, '').replace(/xmlns="http:\/\/www\.w3\.org\/2000\/svg"/g, ''))));
  check('index.html has the PWA metas and the manifest link', (() => { const s = files[0][1]; return ['viewport-fit=cover', 'name="theme-color"', 'apple-mobile-web-app-capable', 'black-translucent', 'mobile-web-app-capable', 'rel="manifest" href="manifest.webmanifest"'].every((k) => s.includes(k)); })());
  check('manifest: name, short_name, standalone, start_url ./index.html, colours, inline SVG icon', (() => { const m = JSON.parse(fs.readFileSync(path.join(GAME_DIR, 'manifest.webmanifest'), 'utf8')); return m.name === 'Synapse League' && m.short_name && m.display === 'standalone' && m.start_url === './index.html' && m.background_color && m.theme_color && m.icons[0].src.startsWith('data:image/svg+xml'); })());
  check('cards.js is a plain data script: top-level const CARD_SET with the set fields, 5 elements, 8 rarities, 9 kinds, 151 cards, 25 variants, 12 rivals, 7 advertisers, the 4 keywords, and the allPrintings/cardOf/isVariant helpers', (() => { const src = fs.readFileSync(path.join(GAME_DIR, 'cards.js'), 'utf8'); if (!/^(\/\/[^\n]*\n|\s)*const CARD_SET = \{/.test(src) || /\brequire\(|\bimport\b|\bexport\b|\bwindow\b|\bdocument\b/.test(src)) return false; const vm = require('vm'); const ctx = {}; vm.createContext(ctx); vm.runInContext(src + '\n;globalThis.CARD_SET = CARD_SET;', ctx); const S = ctx.CARD_SET; return ['name', 'code', 'game', 'elements', 'typeChart', 'rarities', 'bodies', 'moveBands', 'effects', 'kinds', 'cards', 'variants', 'rivals', 'advertisers'].every((k) => S[k] != null) && S.elements.length === 5 && S.rarities.map((r) => r.key).join() === 'C,U,R,H,L,M,IR,SIR' && S.kinds.length === 9 && S.cards.length === 151 && S.variants.length === 25 && typeof ctx.allPrintings === 'function' && ctx.allPrintings().length === 176 && ctx.cardOf('exe12-sir') === S.cards.find((c) => c.id === 'exe12') && ctx.isVariant('exe12-sir') && !ctx.isVariant('exe12') && S.cards.every((c, i) => c.number === i + 1) && S.rivals.length === 12 && S.rivals.every((r, i) => r.rung === i + 1 && r.name && r.initials && typeof r.aiQ === 'number') && S.advertisers.length === 7 && S.advertisers.every((a) => a.key && a.wordmark && a.tagline && a.accent) && Object.keys(S.effects).sort().join() === 'drain,priority,recoil,weaken' && S.cards.every((c) => typeof c.seed === 'number' && c.kind && c.body && c.flavor && c.motif); })());
  const art = fs.readFileSync(path.join(GAME_DIR, 'artifact.html'), 'utf8');
  check('artifact.html: no doctype/html/head/body, starts with <title> + claude:viewport-fit-sides meta, one <style> holding style.css, relative script tags last', !/<!doctype|<html[\s>]|<head[\s>]|<body[\s>]/i.test(art) && art.startsWith('<title>Synapse League</title>\n<meta name="claude:viewport-fit-sides" content="cover">\n<style>') && (art.match(/<style[\s>]/g) || []).length === 1 && art.includes(files[1][1]) && art.trimEnd().endsWith('<script src="cards.js"></script><script src="game.js"></script>'));
  check('style.css: colour tokens on :root, color-scheme dark, body background, height:100% (no 100vh/100dvh), safe-area gutters on #app, no alert/confirm/prompt/window.open in game.js', (() => { const css = files[1][1], js = files[3][1]; return /:root\s*\{[^}]*color-scheme:\s*dark/.test(css) && /body\s*\{[^}]*background:\s*var\(--bg\)/.test(css) && !/100d?vh/.test(css) && /padding-left:\s*max\(16px,\s*env\(safe-area-inset-left/.test(css) && !/\b(alert|confirm|prompt)\s*\(|window\.open\(/.test(js); })());
  check('style.css: no @property dependency (charge and countdown rings are clock-tweened custom properties)', !/@property/.test(files[1][1]));
}

async function httpSuite(page, ctx, base) {
  section = 'http server: ';
  await page.waitForTimeout(250);
  check('loads from http:// with the About card; GAME attached', await page.evaluate(() => !!window.GAME && document.querySelector('[data-overlay="about"]').classList.contains('open')));
  const man = await page.request.get(base + 'manifest.webmanifest');
  check('manifest.webmanifest is served and valid', man.ok() && JSON.parse(await man.text()).display === 'standalone');
  check('onboarding + one auto-battle + one pack work over http', await page.evaluate(() => { GAME.seed(3); GAME.skipAnims(true); GAME.finishOnboarding(); GAME.startBattle({ rung: 2 }); const r = GAME.autoBattle(); if (r.offer) GAME.respondOffer(false); const p = GAME.openPack({ instant: true, free: true }); return GAME.getState().onboarding.step === 6 && !!r.result && p.cards.length === 5; }));
  check('zero console errors and zero page errors', ctx.errors.length === 0, ctx.errors.slice(0, 5));
}

(async () => {
  console.log('== source');
  sourceChecks();
  console.log('== index.html (390×844)');
  const r1 = await withPage((page, ctx) => mainSuite(page, ctx, 'index'), { url: URL_INDEX, name: 'index' });
  console.log('== wrapped artifact.html (390×844)');
  const r2 = await withPage((page, ctx) => mainSuite(page, ctx, 'artifact'), { url: URL_ART, name: 'artifact' });
  console.log('== index.html (desktop)');
  const r3 = await withPage((page, ctx) => desktopSuite(page, ctx), { url: URL_INDEX, name: 'desktop', desktop: true });
  console.log('== index.html over a static http server');
  const { spawn } = require('child_process');
  const port = 8765 + Math.floor(Math.random() * 1000);
  const srv = spawn('python3', ['-m', 'http.server', String(port), '--bind', '127.0.0.1', '--directory', GAME_DIR], { stdio: 'ignore' });
  await new Promise((res) => setTimeout(res, 800));
  const base = `http://127.0.0.1:${port}/`;
  let r4;
  try { r4 = await withPage((page, ctx) => httpSuite(page, ctx, base), { url: base + 'index.html', name: 'http' }); } finally { srv.kill(); }
  const fails = results.filter((r) => !r.ok);
  console.log(`\n${results.length - fails.length}/${results.length} checks passed; console/page errors: index ${r1.errors.length}, artifact ${r2.errors.length}, desktop ${r3.errors.length}, http ${r4.errors.length}`);
  for (const e of [...r1.errors, ...r2.errors, ...r3.errors, ...r4.errors].slice(0, 10)) console.log('  error: ' + e);
  if (fails.length) { console.log('FAILED:'); fails.forEach((f) => console.log('  - ' + f.name)); }
  console.log('screenshots: ' + fs.readdirSync(SHOTS).filter((f) => !f.startsWith('probe')).join(', '));
  try { fs.unlinkSync(WRAPPED); } catch (e) { /* already gone */ }
  process.exit(fails.length ? 1 : 0);
})().catch((e) => { console.error(e); try { fs.unlinkSync(WRAPPED); } catch (err) { /* ignore */ } process.exit(2); });
